// Get all data
const velocityData = $('HTTP: Fetch 12 Weeks Velocity').first()?.json?.weeks || [];
const tradingData = $('HTTP: Fetch 12 Weeks Trading').first()?.json?.weeks || [];
const healthData = $('HTTP: Fetch 12 Weeks System Health').first()?.json?.weeks || [];
const tradeTickets = $('Jira: Fetch TRADE Throughput').all().map(i => i.json);
const infraTickets = $('Jira: Fetch INFRA Throughput').all().map(i => i.json);
const learnTickets = $('Jira: Fetch LEARN Throughput').all().map(i => i.json);
const bugTickets = $('Jira: Fetch Bug Resolution Times').all().map(i => i.json);

// Helper: Calculate linear regression for trend
const calculateTrend = (values) => {
  if (values.length < 3) return { slope: 0, trend: 'insufficient_data', r2: 0 };

  const n = values.length;
  const sumX = values.reduce((s, _, i) => s + i, 0);
  const sumY = values.reduce((s, v) => s + v, 0);
  const sumXY = values.reduce((s, v, i) => s + (i * v), 0);
  const sumX2 = values.reduce((s, _, i) => s + (i * i), 0);

  const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
  const intercept = (sumY - slope * sumX) / n;

  // Calculate R-squared
  const meanY = sumY / n;
  const ssTotal = values.reduce((s, v) => s + Math.pow(v - meanY, 2), 0);
  const ssResidual = values.reduce((s, v, i) => {
    const predicted = slope * i + intercept;
    return s + Math.pow(v - predicted, 2);
  }, 0);
  const r2 = ssTotal > 0 ? 1 - (ssResidual / ssTotal) : 0;

  // Determine trend direction
  let trend = 'stable';
  const slopePercent = meanY > 0 ? (slope / meanY * 100) : 0;
  if (slopePercent > 5) trend = 'improving';
  else if (slopePercent < -5) trend = 'declining';

  return { slope, trend, r2, slopePercent };
};

// Helper: Group tickets by week
const groupByWeek = (tickets) => {
  const weeks = {};
  tickets.forEach(t => {
    const resolved = new Date(t.fields?.resolutiondate || t.fields?.updated);
    const weekStart = new Date(resolved);
    weekStart.setDate(weekStart.getDate() - weekStart.getDay());
    const weekKey = weekStart.toISOString().split('T')[0];
    if (!weeks[weekKey]) weeks[weekKey] = [];
    weeks[weekKey].push(t);
  });
  return weeks;
};

// Calculate velocity trend
const velocityValues = velocityData.map(w => w.points || 0);
const velocityTrend = calculateTrend(velocityValues);
const avgVelocity = velocityValues.length > 0 
  ? velocityValues.reduce((s, v) => s + v, 0) / velocityValues.length 
  : 0;
const lastWeekVelocity = velocityValues[velocityValues.length - 1] || 0;

// Calculate trading P&L trend
const pnlValues = tradingData.map(w => parseFloat(w.totalPnL) || 0);
const pnlTrend = calculateTrend(pnlValues);
const totalPnL = pnlValues.reduce((s, v) => s + v, 0);
const avgWeeklyPnL = pnlValues.length > 0 ? totalPnL / pnlValues.length : 0;
const lastWeekPnL = pnlValues[pnlValues.length - 1] || 0;

// Calculate win rate trend
const winRateValues = tradingData.map(w => parseFloat(w.winRate) || 50);
const winRateTrend = calculateTrend(winRateValues);
const avgWinRate = winRateValues.length > 0 
  ? winRateValues.reduce((s, v) => s + v, 0) / winRateValues.length 
  : 50;

// Calculate system health trend
const uptimeValues = healthData.map(w => parseFloat(w.uptimePercent) || 99);
const uptimeTrend = calculateTrend(uptimeValues);
const avgUptime = uptimeValues.length > 0 
  ? uptimeValues.reduce((s, v) => s + v, 0) / uptimeValues.length 
  : 99;

// Calculate ticket throughput by project
const tradeByWeek = groupByWeek(tradeTickets);
const infraByWeek = groupByWeek(infraTickets);
const learnByWeek = groupByWeek(learnTickets);

const throughputByProject = {
  TRADE: {
    total: tradeTickets.length,
    weeklyAvg: tradeTickets.length / 12,
    weeks: Object.entries(tradeByWeek).map(([w, t]) => ({ week: w, count: t.length }))
  },
  INFRA: {
    total: infraTickets.length,
    weeklyAvg: infraTickets.length / 12,
    weeks: Object.entries(infraByWeek).map(([w, t]) => ({ week: w, count: t.length }))
  },
  LEARN: {
    total: learnTickets.length,
    weeklyAvg: learnTickets.length / 12,
    weeks: Object.entries(learnByWeek).map(([w, t]) => ({ week: w, count: t.length }))
  }
};

// Calculate bug resolution times
const bugResolutionTimes = bugTickets.map(b => {
  const created = new Date(b.fields?.created);
  const resolved = new Date(b.fields?.resolutiondate || b.fields?.updated);
  return (resolved - created) / (1000 * 60 * 60); // hours
}).filter(t => t > 0 && t < 10000); // Filter outliers

const avgBugResolution = bugResolutionTimes.length > 0 
  ? bugResolutionTimes.reduce((s, t) => s + t, 0) / bugResolutionTimes.length 
  : 0;
const medianBugResolution = bugResolutionTimes.length > 0
  ? bugResolutionTimes.sort((a, b) => a - b)[Math.floor(bugResolutionTimes.length / 2)]
  : 0;

// Bug rate trend (bugs per week)
const bugsByWeek = groupByWeek(bugTickets);
const bugRateValues = Object.values(bugsByWeek).map(bugs => bugs.length);
const bugRateTrend = calculateTrend(bugRateValues);
const avgBugRate = bugRateValues.length > 0 
  ? bugRateValues.reduce((s, v) => s + v, 0) / bugRateValues.length 
  : 0;

// Identify alerts for declining trends
const alerts = [];
if (velocityTrend.trend === 'declining' && velocityTrend.r2 > 0.5) {
  alerts.push({
    type: 'velocity_decline',
    severity: 'warning',
    message: `Velocity declining by ${Math.abs(velocityTrend.slopePercent).toFixed(1)}% per week`,
    metric: 'velocity',
    r2: velocityTrend.r2
  });
}

if (pnlTrend.trend === 'declining' && pnlTrend.r2 > 0.4) {
  alerts.push({
    type: 'pnl_decline',
    severity: 'critical',
    message: `Trading P&L declining trend detected`,
    metric: 'pnl',
    r2: pnlTrend.r2
  });
}

if (uptimeTrend.trend === 'declining' && avgUptime < 99) {
  alerts.push({
    type: 'uptime_decline',
    severity: 'critical',
    message: `System uptime declining (avg: ${avgUptime.toFixed(2)}%)`,
    metric: 'uptime',
    r2: uptimeTrend.r2
  });
}

if (bugRateTrend.trend === 'improving' && bugRateTrend.slope > 0.5) {
  // Improving bug rate means more bugs (bad)
  alerts.push({
    type: 'bug_rate_increase',
    severity: 'warning',
    message: `Bug rate increasing by ${bugRateTrend.slope.toFixed(1)} bugs/week`,
    metric: 'bugs',
    r2: bugRateTrend.r2
  });
}

// Check if last Sunday of month for monthly report
const today = new Date();
const nextSunday = new Date(today);
nextSunday.setDate(today.getDate() + 7);
const isLastSundayOfMonth = nextSunday.getMonth() !== today.getMonth();

return {
  json: {
    reportDate: today.toISOString(),
    isMonthlyReport: isLastSundayOfMonth,

    velocity: {
      current: lastWeekVelocity,
      average: avgVelocity.toFixed(1),
      trend: velocityTrend.trend,
      slopePercent: velocityTrend.slopePercent.toFixed(2),
      r2: velocityTrend.r2.toFixed(3),
      history: velocityValues
    },

    trading: {
      lastWeekPnL: lastWeekPnL.toFixed(2),
      totalPnL: totalPnL.toFixed(2),
      avgWeeklyPnL: avgWeeklyPnL.toFixed(2),
      trend: pnlTrend.trend,
      avgWinRate: avgWinRate.toFixed(1),
      winRateTrend: winRateTrend.trend,
      history: pnlValues
    },

    system: {
      avgUptime: avgUptime.toFixed(2),
      trend: uptimeTrend.trend,
      history: uptimeValues
    },

    throughput: throughputByProject,

    bugs: {
      total: bugTickets.length,
      avgResolutionHours: avgBugResolution.toFixed(1),
      medianResolutionHours: medianBugResolution.toFixed(1),
      avgPerWeek: avgBugRate.toFixed(1),
      trend: bugRateTrend.slope > 0 ? 'increasing' : 'decreasing'
    },

    alerts,
    hasAlerts: alerts.length > 0,
    criticalAlerts: alerts.filter(a => a.severity === 'critical').length,

    // Data for visualization
    chartData: {
      velocity: velocityValues,
      pnl: pnlValues,
      winRate: winRateValues,
      uptime: uptimeValues,
      bugRate: bugRateValues
    }
  }
};

const data = $input.first().json;

const prompt = `You are a data analyst specializing in software development and trading system metrics.

Analyze these 12-week trends and provide insights with forecasts:

## VELOCITY TREND
- Current: ${data.velocity.current} story points
- 12-week Average: ${data.velocity.average} points
- Trend: ${data.velocity.trend} (${data.velocity.slopePercent}% per week)
- R-squared: ${data.velocity.r2}
- History: ${data.velocity.history.join(', ')}

## TRADING PERFORMANCE
- Last Week P&L: $${data.trading.lastWeekPnL}
- 12-week Total: $${data.trading.totalPnL}
- Weekly Average: $${data.trading.avgWeeklyPnL}
- Trend: ${data.trading.trend}
- Win Rate: ${data.trading.avgWinRate}% (${data.trading.winRateTrend})
- P&L History: ${data.trading.history.join(', ')}

## SYSTEM HEALTH
- Average Uptime: ${data.system.avgUptime}%
- Trend: ${data.system.trend}
- History: ${data.system.history.join(', ')}

## TICKET THROUGHPUT
- TRADE: ${data.throughput.TRADE.total} tickets (${data.throughput.TRADE.weeklyAvg.toFixed(1)}/week)
- INFRA: ${data.throughput.INFRA.total} tickets (${data.throughput.INFRA.weeklyAvg.toFixed(1)}/week)
- LEARN: ${data.throughput.LEARN.total} tickets (${data.throughput.LEARN.weeklyAvg.toFixed(1)}/week)

## BUG METRICS
- Total Resolved: ${data.bugs.total}
- Avg Resolution: ${data.bugs.avgResolutionHours} hours
- Median Resolution: ${data.bugs.medianResolutionHours} hours
- Rate Trend: ${data.bugs.trend}

## ACTIVE ALERTS
${data.alerts.length > 0 ? data.alerts.map(a => '- [' + a.severity.toUpperCase() + '] ' + a.message).join('\n') : 'No active alerts'}

${data.isMonthlyReport ? '## NOTE: This is a MONTHLY report - include month-over-month comparison' : ''}

---

Provide analysis in this format:

## TREND INTERPRETATION
(What the numbers mean for the business - 3-4 bullets)

## FORECAST
(Project next 2-4 weeks based on trends - be specific with numbers)

## CONCERNS
(Any worrying patterns or correlations - 2-3 items)

## RECOMMENDATIONS
(Specific actions to improve metrics - 3-4 actionable items)

## POSITIVE MOMENTUM
(Highlight improving areas - 2-3 wins)

Be data-driven and specific. Reference actual numbers. Max 400 words.`;

return {
  json: {
    prompt,
    data,
    isMonthlyReport: data.isMonthlyReport
  }
};

const response = $json;
const prevData = $('Code: Build Trend Analysis Prompt').first().json;

// Extract analysis text
let analysisText = '';
if (response?.content?.[0]?.text) {
  analysisText = response.content[0].text;
} else {
  analysisText = 'Failed to generate trend analysis. Please review manually.';
}

return {
  json: {
    analysisText,
    data: prevData.data,
    isMonthlyReport: prevData.isMonthlyReport
  }
};

