      value: `$${metrics.trading.totalPnL}`,
      inline: true
    },
    {
      name: ':dart: Avg Win Rate',
      value: `${metrics.trading.avgWinRate}%`,
      inline: true
    },
    {
      name: ':shield: Avg Uptime',
      value: `${metrics.system.avgUptime}%`,
      inline: true
    },
    {
      name: ':bug: Bug Resolution',
      value: `${metrics.bugs.medianResolutionHours}h median`,
      inline: true
    },
    {
