      inline: true
    },
    {
      name: ':wrench: INFRA Throughput',
      value: `${metrics.throughput.INFRA.total} (${metrics.throughput.INFRA.weeklyAvg.toFixed(1)}/wk)`,
      inline: true
    },
    {
      name: ':books: LEARN Throughput',
      value: `${metrics.throughput.LEARN.total} (${metrics.throughput.LEARN.weeklyAvg.toFixed(1)}/wk)`,
      inline: true
    }
  ],
  footer: {
    text: 'SwjshAK Monthly Velocity Report | WF-MGMT-02'
  },
  timestamp: new Date().toISOString()
};

return {
  json: {
    embed,
    monthName,
    data,
    channelId: process.env.DISCORD_CEO_CHANNEL_ID || 'ceo-briefing'
  }
};

